'use client';

import * as React from 'react';
import {createComponent} from '@lit/react';
import '@material/web/labs/gb/components/progress/md-gb-progress.js';
import {ProgressElement} from '@material/web/labs/gb/components/progress/progress-element.js';

/**
 * A Material Design component. Wraps <md-gb-progress>.
 * Docs: https://material-web.dev/3.0/components/progress/
 */
export const MdProgress = createComponent({
  react: React,
  tagName: 'md-gb-progress',
  elementClass: ProgressElement,
});

export type MdProgressProps = React.ComponentProps<typeof MdProgress>;
